PROGRAM = 'from collections import Counter\n\nDIAG = ((-1, -1), (-1, 1), (1, -1), (1, 1))\nORTH = ((-1, 0), (1, 0), (0, -1), (0, 1))\n\n\ndef _inside(y, x, H, W):\n    return 0 <= y < H and 0 <= x < W\n\n\ndef _components(g, bg, H, W):\n    seen = [[False] * W for _ in range(H)]\n    comps = []\n    for r in range(H):\n        for c in range(W):\n            if seen[r][c] or g[r][c] == bg:\n                continue\n            col = g[r][c]\n            seen[r][c] = True\n            stack = [(r, c)]\n            cells = []\n            while stack:\n                y, x = stack.pop()\n                cells.append((y, x))\n                for dy, dx in ORTH:\n                    ny, nx = y + dy, x + dx\n                    if _inside(ny, nx, H, W) and not seen[ny][nx] and g[ny][nx] == col:\n                        seen[ny][nx] = True\n                        stack.append((ny, nx))\n            comps.append((col, sorted(cells)))\n    return comps\n\n\ndef _head_first(cells, H, W):\n    cells = sorted(cells)\n    if len(cells) < 3:\n        raise ValueError("At least three sequence cells required")\n    if len(set(r for r, _ in cells)) == 1:\n        step = (0, 1)\n    elif len(set(c for _, c in cells)) == 1:\n        step = (1, 0)\n    else:\n        raise ValueError("Sequence cells must be collinear")\n    if any((b[0]-a[0],b[1]-a[1]) != step for a,b in zip(cells,cells[1:])):\n        raise ValueError("Sequence cells must be contiguous")\n    a, b = cells[0], cells[-1]\n    a_open = _inside(a[0] - step[0], a[1] - step[1], H, W)\n    b_open = _inside(b[0] + step[0], b[1] + step[1], H, W)\n    if a_open and not b_open:\n        return cells\n    if b_open and not a_open:\n        return cells[::-1]\n    raise ValueError("Sequence needs one border endpoint")\n\n\ndef solve(demonstrations, grid):\n    g = [[int(v) for v in row] for row in grid]\n    H = len(g)\n    if H == 0 or len(g[0]) == 0:\n        return g\n    W = len(g[0])\n    bg = Counter(v for row in g for v in row).most_common(1)[0][0]\n    comps = _components(g, bg, H, W)\n    singles = [cells[0] for col, cells in comps if len(cells) == 1]\n    markers = [(col, cells) for col, cells in comps if len(cells) >= 2]\n    if any(len(cells)!=2 for col,cells in markers):\n        raise ValueError("Markers must be two-cell dominoes")\n    out = [row[:] for row in g]\n    for y0, x0 in _head_first(singles, H, W):\n        col = g[y0][x0]\n        for dy, dx in DIAG:\n            y, x = y0 + dy, x0 + dx\n            while _inside(y, x, H, W) and out[y][x] == bg:\n                out[y][x] = col\n                y += dy\n                x += dx\n    marker_cells = {p: col for col,cells in markers for p in cells}\n    seen=set()\n    for r in range(H):\n        for c in range(W):\n            if out[r][c]!=bg or (r,c) in seen:continue\n            region=[];seeds=set();stack=[(r,c)];seen.add((r,c))\n            while stack:\n                y,x=stack.pop();region.append((y,x))\n                for dy,dx in ORTH:\n                    ny,nx=y+dy,x+dx\n                    if (ny,nx) in marker_cells:seeds.add(marker_cells[ny,nx])\n                    if _inside(ny,nx,H,W) and out[ny][nx]==bg and (ny,nx) not in seen:\n                        seen.add((ny,nx));stack.append((ny,nx))\n            if len(seeds)>1:raise ValueError(\'Different marker colours share a flood region\')\n            if seeds:\n                colour=next(iter(seeds))\n                for y,x in region:out[y][x]=colour\n    return out\n'

def build_program(d4,palette):
    return PROGRAM
